// ============================================
// PRÉPARATION MESSAGE TELEGRAM (NETTOYAGE + FORMATAGE)
// ============================================

const text = $json["agent_output"] || $json["output"] || $json["Output"] || $json["message"] || "";

if (!text || text.length === 0) {
  return [{ json: { error: "Aucun texte à envoyer" } }];
}

let cleanText = text;

// 1. SUPPRESSION MARKDOWN
cleanText = cleanText.replace(/\*\*/g, '');  // **texte** → texte
cleanText = cleanText.replace(/\*/g, '');    // *texte* → texte
cleanText = cleanText.replace(/___/g, '');   // ___texte___ → texte
cleanText = cleanText.replace(/__/g, '');    // __texte__ → texte
cleanText = cleanText.replace(/_/g, '');     // _texte_ → texte
cleanText = cleanText.replace(/##/g, '');    // ## titre → titre
cleanText = cleanText.replace(/#/g, '');     // # titre → titre

// 2. NETTOYAGE DES GUILLEMETS SUPERFLUS
cleanText = cleanText.replace(/^[""]|[""]$/g, ''); // Guillemets début/fin

// 3. AMÉLIORATION DES PARAGRAPHES
// Remplacer \n\n par vrai double saut (conserver structure)
cleanText = cleanText.replace(/\n\n+/g, '\n\n');

// 4. AMÉLIORATION DES LISTES
// Garder les tirets pour les listes mais nettoyer
cleanText = cleanText.replace(/^- /gm, '• ');  // - → •

// 5. NETTOYAGE ESPACES EXCESSIFS
cleanText = cleanText.replace(/ {2,}/g, ' ');  // Espaces multiples → 1 espace
cleanText = cleanText.replace(/\n /g, '\n');   // Espace après \n

// 6. NETTOYAGE HTML NON SUPPORTÉ PAR TELEGRAM
cleanText = cleanText.replace(/<(?!\/?(?:b|strong|i|em|u|s|code|pre|a)(?:\s|>))[^>]+>/g, '');

// 7. TRIM GÉNÉRAL
cleanText = cleanText.trim();

// 8. DÉCOUPER EN CHUNKS DE 4000 CARACTÈRES
const chunkSize = 4000;
let messages = [];

for (let i = 0; i < cleanText.length; i += chunkSize) {
  messages.push({
    json: {
      message: cleanText.slice(i, i + chunkSize)
    }
  });
}

console.log(`📤 Message nettoyé: ${messages.length} chunk(s), ${cleanText.length} caractères`);
return messages;

